(* [comment removed for export] *)
Definition nodesW (X : list Z) : list (Z * Z) := map (fun a => (a, a + 32)) X.
Definition ibW (lo hi : Z) (X : list Z) : list (Z * Z) := (lo, hi) :: nodesW X.

Lemma inside_ibW_frame : forall lo hi X a n, lo <= a -> a + n <= hi -> inside (ibW lo hi X) a n.
Proof. intros lo hi X a n H1 H2. cbn. left. lia. Qed.

Lemma inside_nodesW : forall X x a n, x ∈ X -> x <= a -> a + n <= x + 32 -> inside (nodesW X) a n.
Proof.
  intros X x a n IN H1 H2. induction X as [|y X IH]; [rewrite elem_of_nil in IN; destruct IN|].
  cbn. rewrite elem_of_cons in IN. destruct IN as [<-|IN]; [left; lia| right; exact (IH IN)].
Qed.

Lemma inside_ibW_node : forall lo hi X x a n, x ∈ X -> x <= a -> a + n <= x + 32 -> inside (ibW lo hi X) a n.
Proof. intros lo hi X x a n IN H1 H2. cbn. right. eapply inside_nodesW; eauto. Qed.

Lemma disjoint_nodesW : forall X a n, (forall x, x ∈ X -> a + n <= x \/ x + 32 <= a) -> disjoint_from (nodesW X) a n.
Proof.
  intros X a n H. induction X as [|y X IH]; [exact I|]. cbn. split.
  - apply H. rewrite elem_of_cons. left; reflexivity.
  - apply IH. intros x IN. apply H. rewrite elem_of_cons. right; exact IN.
Qed.

Lemma disjoint_ibW : forall lo hi X a n, (a + n <= lo \/ hi <= a) ->
  (forall x, x ∈ X -> a + n <= x \/ x + 32 <= a) -> disjoint_from (ibW lo hi X) a n.
Proof. intros lo hi X a n H1 H2. cbn. split; [exact H1| apply disjoint_nodesW; exact H2]. Qed.

Lemma outside_nodesW : forall X u, outside (nodesW X) u <-> (forall x, x ∈ X -> ~ (x <= u < x + 32)).
Proof.
  intros X u. induction X as [|y X IH]; cbn.
  - split; [intros _ x IN; rewrite elem_of_nil in IN; destruct IN| intros; exact I].
  - rewrite IH. split.
    + intros [H1 H2] x IN. rewrite elem_of_cons in IN. destruct IN as [<-|IN]; [exact H1| exact (H2 x IN)].
    + intros H. split; [apply H; rewrite elem_of_cons; left; reflexivity|]. intros x IN. apply H. rewrite elem_of_cons. right; exact IN.
Qed.

(* [comment removed for export] *)
Lemma munch_ibW_of_frame : forall lo hi X lo' hi' m m', munch [(lo', hi')] m m' -> lo <= lo' -> hi' <= hi -> munch (ibW lo hi X) m m'.
Proof.
  intros lo hi X lo' hi' m m' MU H1 H2. eapply munch_weaken; [| exact MU]. intros u [K _]. cbn. split; [lia| exact I].
Qed.

Lemma munch_ibW_mono : forall lo hi lo' hi' X m m', munch (ibW lo' hi' X) m m' -> lo <= lo' -> hi' <= hi -> munch (ibW lo hi X) m m'.
Proof.
  intros lo hi lo' hi' X m m' MU H1 H2. eapply munch_weaken; [| exact MU]. intros u [K R]. cbn. split; [lia| exact R].
Qed.

(* [comment removed for export] *)
Lemma munch_ibW_of_inside : forall lo hi X W m m',
  munch W m m' -> Forall (fun iv : Z * Z => lo <= fst iv /\ snd iv <= hi) W -> munch (ibW lo hi X) m m'.
Proof.
  intros lo hi X W m m' MU F. eapply munch_weaken; [| exact MU]. intros u [K _]. cbn in K. clear MU.
  induction W as [|[a b] W IH]; [exact I|]. cbn. pose proof (Forall_inv F) as K1. cbn in K1.
  split; [lia| apply IH; exact (Forall_inv_tail F)].
Qed.

(* [comment removed for export] *)
Lemma munch_ibW_sub : forall lo hi X X' m m', munch (ibW lo hi X) m m' -> (forall x, x ∈ X -> x ∈ X') -> munch (ibW lo hi X') m m'.
Proof.
  intros lo hi X X' m m' MU SUB. eapply munch_weaken; [| exact MU]. intros u [K R]. cbn. split; [exact K|].
  rewrite outside_nodesW in R |- *. intros x IN. apply R. apply SUB. exact IN.
Qed.

(* [comment removed for export] *)
Lemma mb_load {R} (ns : NS) x off nd (K : Z -> option R) r :
  ns !! x = Some nd -> (load ns x off ≫= K) = Some r -> K (get_field off nd) = Some r.
Proof. intros L H. unfold load in H. rewrite L in H. exact H. Qed.
Lemma mb_store {R} (ns : NS) x off v nd (K : NS -> option R) r :
  ns !! x = Some nd -> (store ns x off v ≫= K) = Some r -> K (<[x := set_field off v nd]> ns) = Some r.
Proof. intros L H. unfold store in H. rewrite L in H. exact H. Qed.
Lemma m_load_last (ns : NS) x off nd r : ns !! x = Some nd -> load ns x off = Some r -> r = get_field off nd.
Proof. intros L H. unfold load in H. rewrite L in H. cbn in H. congruence. Qed.
Lemma m_store_last (ns : NS) x off v nd r : ns !! x = Some nd -> store ns x off v = Some r -> r = <[x := set_field off v nd]> ns.
Proof. intros L H. unfold store in H. rewrite L in H. cbn in H. congruence. Qed.

