(* [comment removed for export] *)
Lemma rw_cells_ibW : forall lo hi X m m' A cs,
  rw_cells usegs m A cs -> munch (ibW lo hi X) m m' -> wmono usegs m m' ->
  (A + Z.of_nat (cells_size cs) <= lo \/ hi <= A) ->
  (forall x, x ∈ X -> A + Z.of_nat (cells_size cs) <= x \/ x + 32 <= A) ->
  rw_cells usegs m' A cs.
Proof.
  intros lo hi X m m' A cs H MU WM D1 D2. eapply rw_cells_transport; [exact H| exact MU| exact WM|]. apply disjoint_ibW; assumption.
Qed.

Lemma bytes_at_ibW : forall lo hi X m m' A bs,
  bytes_at usegs m A bs -> munch (ibW lo hi X) m m' ->
  (A + Z.of_nat (length bs) <= lo \/ hi <= A) ->
  (forall x, x ∈ X -> A + Z.of_nat (length bs) <= x \/ x + 32 <= A) ->
  bytes_at usegs m' A bs.
Proof.
  intros lo hi X m m' A bs H MU D1 D2. eapply bytes_at_transport; [exact H| exact MU|]. apply disjoint_ibW; assumption.
Qed.

Lemma EMCells_ibW : forall lo hi X m m' em,
  EMCells m em -> munch (ibW lo hi X) m m' -> wmono usegs m m' ->
  (forall e d, em !! e = Some d -> e + esize d <= lo \/ hi <= e + 48) ->
  (forall e d x, em !! e = Some d -> x ∈ X -> e + esize d <= x \/ x + 32 <= e + 48) ->
  EMCells m' em.
Proof.
  intros lo hi X m m' em H MU WM D1 D2 e d L. eapply rw_cells_ibW; [exact (H e d L)| exact MU| exact WM| |].
  - rewrite ValCells_size. pose proof (D1 e d L). lia.
  - intros x IN. rewrite ValCells_size. pose proof (D2 e d x L IN). lia.
Qed.

Lemma LSCells_ibW : forall lo hi X m m' ls,
  LSCells m ls -> munch (ibW lo hi X) m m' -> wmono usegs m m' ->
  (forall a n, ls !! a = Some n -> a + 16 <= lo \/ hi <= a) ->
  (forall a n x, ls !! a = Some n -> x ∈ X -> a + 16 <= x \/ x + 32 <= a) ->
  LSCells m' ls.
Proof.
  intros lo hi X m m' ls H MU WM D1 D2 a n L. destruct (H a n L) as [WF C]. split; [exact WF|].
  eapply rw_cells_ibW; [exact C| exact MU| exact WM| |].
  - rewrite LNodeCells_size. exact (D1 a n L).
  - intros x IN. rewrite LNodeCells_size. exact (D2 a n x L IN).
Qed.

(* [comment removed for export] *)
Definition NSR (m : mem) (ns : NS) (lo hi : Z) (X : list Z) : Prop :=
  NSCells m ns /\ ns_sep ns /\ (forall x, x ∈ X -> x + 32 <= lo \/ hi <= x) /\ (forall a nd, ns !! a = Some nd -> a ∈ X).

Lemma NSR_out : forall m ns lo hi X, NSR m ns lo hi X -> ns_out ns lo hi.
Proof. intros m ns lo hi X (NC & SEP & XO & INX) a nd L. exact (XO a (INX a nd L)). Qed.

Lemma NSR_Xout : forall m ns lo hi X x, NSR m ns lo hi X -> x ∈ X -> x + 32 <= lo \/ hi <= x.
Proof. intros m ns lo hi X x (NC & SEP & XO & INX) IN. exact (XO x IN). Qed.

Lemma NSR_cells : forall m ns lo hi X, NSR m ns lo hi X -> NSCells m ns.
Proof. intros m ns lo hi X (NC & _). exact NC. Qed.

Lemma NSR_intro : forall m ns lo hi X,
  NSCells m ns -> ns_sep ns -> (forall x, x ∈ X -> x + 32 <= lo \/ hi <= x) -> (forall a, is_Some (ns !! a) -> a ∈ X) ->
  NSR m ns lo hi X.
Proof.
  intros m ns lo hi X NC SEP XO INX. split; [exact NC|]. split; [exact SEP|]. split; [exact XO|].
  intros a nd L. apply INX. rewrite L. eexists; reflexivity.
Qed.

(* [comment removed for export] *)
Lemma NSR_recells : forall m m' ns lo hi X, NSR m ns lo hi X -> NSCells m' ns -> NSR m' ns lo hi X.
Proof. intros m m' ns lo hi X (NC & SEP & XO & INX) NC'. split; [exact NC'|]. split; [exact SEP|]. split; [exact XO| exact INX]. Qed.

Lemma NSR_node : forall m ns lo hi X a nd, NSR m ns lo hi X -> ns !! a = Some nd ->
  node_wf nd /\ a ∈ X /\ (a + 32 <= lo \/ hi <= a) /\ exists pad, rw_cells usegs m a (NodeCells nd pad).
Proof.
  intros m ns lo hi X a nd (NC & SEP & OUT & INX) L.
  split; [exact (NSCells_wf _ _ _ _ NC L)|]. split; [exact (INX a nd L)|]. split; [exact (OUT a (INX a nd L))|].
  exact (NSCells_lookup _ _ _ _ NC L).
Qed.

Lemma NSR_sep : forall m ns lo hi X a b nda ndb, NSR m ns lo hi X -> ns !! a = Some nda -> ns !! b = Some ndb -> a <> b ->
  a + 32 <= b \/ b + 32 <= a.
Proof. intros m ns lo hi X a b nda ndb (NC & SEP & OUT & INX) La Lb NE. exact (SEP a b nda ndb La Lb NE). Qed.

Lemma NSR_transport_frame : forall m m' ns lo hi X lo' hi',
  NSR m ns lo hi X -> munch [(lo', hi')] m m' -> wmono usegs m m' -> lo <= lo' -> hi' <= hi -> NSR m' ns lo hi X.
Proof.
  intros m m' ns lo hi X lo' hi' NSR0 MU WM H1 H2. pose proof NSR0 as (NC & SEP & OUT & INX).
  split; [| split; [exact SEP| split; [exact OUT| exact INX]]].
  eapply NSCells_transport_out; [exact NC| exact MU| exact WM| eapply NSR_out; exact NSR0|]. constructor; [cbn; lia| constructor].
Qed.
